/* ---------- conseils du jour ---------- */
const CONSEILS=['Prenez une multivitamine avec 0,4 mg d\'acide folique chaque jour, idéalement au moins 3 mois avant la conception.','Pendant la fenêtre fertile, des rapports tous les 1 à 2 jours donnent les meilleures chances, sans pression d\'horaire.','Les spermatozoïdes peuvent vivre jusqu\'à 5 jours, l\'ovule de 12 à 24 heures : les jours avant l\'ovulation comptent autant que le jour même.','Testez l\'ovulation en après-midi, à peu près à la même heure chaque jour, en buvant moins dans les 2 heures avant.','La température basale se prend au réveil, avant de vous lever, après au moins 3 heures de sommeil.','La glaire « blanc d\'œuf », claire et filante, annonce souvent les jours les plus fertiles.','Limitez la caféine à environ 300 mg par jour (2 petits cafés) et évitez l\'alcool, le tabac et le cannabis.','Le partenaire aussi prépare la grossesse : éviter le tabac, l\'alcool en excès et la chaleur prolongée (bains très chauds, ordinateur sur les cuisses).','Faites vérifier vos vaccins (rubéole, varicelle) et vos médicaments avec votre médecin avant de concevoir.','Le stress n\'empêche pas à lui seul de concevoir, mais prendre soin de vous rend le parcours plus doux.','Certains lubrifiants nuisent aux spermatozoïdes : choisissez-en un « compatible avec la fertilité » au besoin.','Il est normal que ça prenne quelques mois : environ 8 couples sur 10 conçoivent dans l\'année.','Un test de grossesse est fiable dès le jour des règles attendues, avec la première urine du matin.','Bouger 150 minutes par semaine, bien dormir et manger varié aident votre fertilité et votre future grossesse.'];
/* ---------- formulaires ---------- */
const dateAuj=()=>iso(new Date());
function fRegles(){sheet('Début des règles','<label class="f">Premier jour des règles<input type="date" id="ft_d" value="'+dateAuj()+'" max="'+dateAuj()+'"></label><div class="grid2"><label class="f">Durée (jours, si connue)<input type="number" id="ft_j" inputmode="numeric" min="1" max="12" placeholder="'+((cycle().dureeR)||5)+'"></label><label class="f">Flux<select id="ft_f"><option value="">—</option>'+Object.entries(FLUX).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label></div><button class="btn" data-ft-save="regles">Enregistrer</button>')}
function fRapport(){sheet('Rapport','<p class="small muted">Noter vos rapports aide à voir s\'ils tombent pendant la fenêtre fertile. Ces notes restent privées.</p>'+W()+'<label class="check"><input type="checkbox" id="ft_prot"><span>Rapport protégé (préservatif ou autre méthode)</span></label><button class="btn" data-ft-save="rapport">Enregistrer</button>')}
function fTemp(){sheet('Température basale','<label class="f">Température (°C)<input type="number" id="ft_c" inputmode="decimal" step="0.01" min="35" max="38.5" placeholder="Ex. : 36,45"></label>'+W()+'<p class="xs muted">Au réveil, avant de vous lever, à la même heure chaque jour, avec un thermomètre précis à 0,01 °C.</p><button class="btn" data-ft-save="temp">Enregistrer</button>')}
function fGlaire(){sheet('Glaire cervicale','<div class="stack" style="gap:8px">'+Object.entries(GL).map(([k,v])=>'<button class="btn ghost" data-ft-gl="'+k+'">'+v+'</button>').join('')+'</div><p class="xs muted">« Blanc d\'œuf » (claire, élastique) : souvent les jours les plus fertiles.</p>')}
function fTestG(){sheet('Test de grossesse','<p class="small">Quel est le résultat ?</p><div class="grid2"><button class="btn ghost" data-ft-tg="neg">Négatif</button><button class="btn" data-ft-tg="pos">Positif 💗</button></div><p class="xs muted">Le plus fiable : à partir du jour des règles attendues, avec la première urine du matin. Un résultat négatif tôt peut devenir positif quelques jours plus tard.</p>')}
/* test d'ovulation : photo, puis on touche la ligne de contrôle (C) et la ligne de test (T) pour comparer leur intensité */
let OVT=null;
function fOvul(){OVT={};sheet('Test d\'ovulation','<p class="small">Prenez une photo du test bien à plat, à la lumière du jour, au temps de lecture indiqué sur la boîte.</p><label class="btn" style="text-align:center">'+icon('fa-camera')+'Prendre ou choisir la photo<input type="file" id="ft_ph" accept="image/*" capture="environment" hidden></label>'+
  '<div id="ft_zone" style="display:none;margin-top:10px"><p class="small" id="ft_inst"><b>1.</b> Touchez la <b>ligne de contrôle (C)</b>.</p><div class="ft-cv"><canvas id="ft_cv"></canvas></div><div id="ft_res" class="ft-res"></div></div>'+
  '<label class="f" style="margin-top:10px">Résultat<select id="ft_r"><option value="">— lecture automatique ou choisissez —</option>'+Object.entries(OV).map(([k,v])=>'<option value="'+k+'">'+v[0]+'</option>').join('')+'</select></label>'+W()+
  '<p class="xs muted">Lecture indicative : la ligne de test aussi foncée ou plus foncée que la ligne de contrôle = pic de LH, l\'ovulation suit souvent dans les 24 à 36 heures. Fiez-vous à la notice de votre test.</p><button class="btn" data-ft-save="ovul">Enregistrer</button>')}
function chargerPhoto(f){const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,900/Math.max(im.width,im.height)),cv=$('#ft_cv');cv.width=Math.round(im.width*k);cv.height=Math.round(im.height*k);
  const cx=cv.getContext('2d');cx.drawImage(im,0,0,cv.width,cv.height);OVT={img:im,w:cv.width,h:cv.height,data:cx.getImageData(0,0,cv.width,cv.height).data,C:null,T:null};$('#ft_zone').style.display='';
  const t=document.createElement('canvas'),k2=Math.min(1,480/Math.max(im.width,im.height));t.width=Math.round(im.width*k2);t.height=Math.round(im.height*k2);t.getContext('2d').drawImage(im,0,0,t.width,t.height);OVT.mini=t.toDataURL('image/jpeg',.7)};im.src=fr.result};fr.readAsDataURL(f)}
function intensite(x,y){x=Math.round(x);y=Math.round(y);const D=OVT.data,w=OVT.w,h=OVT.h,r=Math.max(5,Math.round(Math.max(w,h)/70)),R=r*3,v=(i,j)=>{i=Math.max(0,Math.min(w-1,i));j=Math.max(0,Math.min(h-1,j));const p=(j*w+i)*4;return 255-D[p+1]};
  const dedans=[],autour=[];for(let j=-R;j<=R;j+=1)for(let i=-R;i<=R;i+=1){const a=Math.abs(i)<=r&&Math.abs(j)<=r;if(a)dedans.push(v(x+i,y+j));else if((i+j)%2===0)autour.push(v(x+i,y+j))}
  dedans.sort((a,b)=>b-a);autour.sort((a,b)=>a-b);const ligne=dedans.slice(0,Math.max(1,Math.round(dedans.length*.25))).reduce((s,a)=>s+a,0)/Math.max(1,Math.round(dedans.length*.25)),fond=autour[Math.round(autour.length*.3)]||0;
  return Math.max(0,ligne-fond)}
function dessiner(){const cv=$('#ft_cv');if(!cv||!OVT.img)return;const cx=cv.getContext('2d');cx.drawImage(OVT.img,0,0,cv.width,cv.height);
  [['C',OVT.C,'#2563eb'],['T',OVT.T,'#c2410c']].forEach(([n,p,c])=>{if(!p)return;cx.strokeStyle=c;cx.lineWidth=3;cx.beginPath();cx.arc(p[0],p[1],Math.max(10,cv.width/30),0,7);cx.stroke();cx.fillStyle=c;cx.font='bold '+Math.max(14,cv.width/22)+'px sans-serif';cx.fillText(n,p[0]+Math.max(12,cv.width/26),p[1]-8)})}
function lire(){const c=intensite(OVT.C[0],OVT.C[1]),t=intensite(OVT.T[0],OVT.T[1]);if(c<8){$('#ft_res').innerHTML='<span class="small">La ligne de contrôle n\'est pas assez visible : reprenez la photo plus près, à la lumière.</span>';return}
  const r=t/c;OVT.ratio=r;const res=r>=1?'pic':r>=0.8?'pos':r>=0.4?'hausse':'neg';$('#ft_r').value=res;
  $('#ft_res').innerHTML='<span class="pill" style="background:'+OV[res][1]+';color:#fff">'+OV[res][0]+'</span> <span class="small">Ligne T ≈ '+Math.round(r*100)+' % de la ligne C.</span> <button class="btn sm ghost" data-ft-reset="1">Recommencer</button>'}
/* ---------- pages ---------- */
function tete(){const nm=S.parent.prenom&&S.parent.prenom!=='Exemple'?esc(S.parent.prenom):'';return '<div class="sh"><span class="script">Bonjour'+(nm?' '+nm:'')+'</span><h1>Mon cycle</h1></div>'}
function boutons(){const B=[['regles','🩸','Règles'],['rapport','❤️','Rapport'],['ovul','🧪','Test ovulation'],['temp','🌡️','Température'],['glaire','💧','Glaire'],['testg','🤰','Test grossesse'],['traitement','💉','Traitement'],['avenir','📅','À venir']];
  return '<div class="ft-btns">'+B.map(b=>'<button class="ft-b" data-ft-add="'+b[0]+'"><span>'+b[1]+'</span><b>'+b[2]+'</b></button>').join('')+'</div>'}
function semaine(C){let h='<div class="ft-sem">';for(let i=-1;i<6;i++){const d=j0(Date.now())+i*J,s=statut(d,C);h+='<div class="ft-j '+s+(i===0?' auj':'')+'"><span>'+fd(d,{weekday:'short'}).replace('.','')+'</span><b>'+new Date(d).getDate()+'</b></div>'}return h+'</div>'}
/* ---------- ma situation : pour adapter les repères (SOPK, endométriose, contraception, allaitement, âge, clinique…) ---------- */
const COND={sopk:'SOPK (syndrome des ovaires polykystiques)',endo:'Endométriose',thyro:'Problème de thyroïde',irreg:'Cycles irréguliers',contra:'Contraception hormonale arrêtée depuis moins de 6 mois',depo:'Injection contraceptive (Depo-Provera) arrêtée récemment',allait:'J\'allaite',fc:'2 fausses couches ou plus',clinique:'Suivie en clinique de fertilité (IIU, FIV…)',partenaire:'Problème connu chez le partenaire'};
const prof=()=>S.parent.ftProfil||{};
const irregulier=()=>{const p=prof(),c=p.conds||[];return c.includes('sopk')||c.includes('irreg')||c.includes('allait')||c.includes('depo')||p.regulier==='non'};
function fProfil(apres){const p=prof(),c=p.conds||[];
  sheet('Pour adapter vos repères','<p class="small muted">Ces réponses restent dans votre espace. Elles servent à adapter les prévisions et les conseils.</p>'+
   '<label class="f">Vos cycles sont-ils réguliers (même durée à quelques jours près) ?<select id="fp_reg"><option value="">—</option>'+[['oui','Oui'],['non','Non, ils varient beaucoup'],['nsp','Je ne sais pas']].map(o=>'<option value="'+o[0]+'"'+(p.regulier===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')+'</select></label>'+
   '<div class="grid2"><label class="f">Durée habituelle du cycle (jours)<input type="number" id="fp_cl" min="18" max="60" value="'+(+S.parent.cycleLen||28)+'"></label><label class="f">Votre âge<select id="fp_age"><option value="">—</option>'+[['m35','Moins de 35 ans'],['35','35 à 39 ans'],['40','40 ans ou plus']].map(o=>'<option value="'+o[0]+'"'+(p.age===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')+'</select></label></div>'+
   '<p class="small" style="margin:10px 0 4px"><b>Cochez ce qui vous concerne</b></p><div class="stack" style="gap:4px">'+Object.entries(COND).map(([k,v])=>'<label class="check"><input type="checkbox" data-fp="'+k+'"'+(c.includes(k)?' checked':'')+'><span>'+v+'</span></label>').join('')+'</div>'+
   '<label class="f" style="margin-top:8px">Depuis combien de mois essayez-vous ?<input type="number" id="fp_mois" min="0" max="240" value="'+(p.mois!=null?p.mois:'')+'" placeholder="Ex. : 4"></label>'+
   '<label class="f">Autre information importante (facultatif)<input id="fp_note" value="'+esc(p.note||'')+'"></label><button class="btn" data-fp-save="1">Enregistrer</button>')}
function pourVous(){const p=prof(),c=p.conds||[],T=[];
  if(c.includes('sopk'))T.push('<b>SOPK</b> : l\'ovulation peut être irrégulière ou absente, et les tests d\'ovulation peuvent être positifs plusieurs jours sans ovulation. La glaire et la température aident à confirmer. Parlez-en à votre médecin dès maintenant : des traitements simples existent pour aider l\'ovulation.');
  if(c.includes('endo'))T.push('<b>Endométriose</b> : il est recommandé de consulter sans attendre les 12 mois habituels, surtout si les règles ou les rapports sont douloureux.');
  if(c.includes('thyro'))T.push('<b>Thyroïde</b> : un bon contrôle avant et pendant la grossesse est important. Faites vérifier votre traitement avec votre médecin.');
  if(c.includes('irreg')||p.regulier==='non')T.push('<b>Cycles irréguliers</b> : les dates prévues sont approximatives. Fiez-vous surtout aux tests d\'ovulation, à la glaire et à la température. Des cycles très irréguliers ou absents méritent une consultation.');
  if(c.includes('contra'))T.push('<b>Arrêt récent de la contraception</b> : la fertilité revient vite pour la plupart, mais les cycles peuvent prendre quelques mois à se régulariser.');
  if(c.includes('depo'))T.push('<b>Injection contraceptive</b> : le retour des ovulations peut prendre plusieurs mois après la dernière injection. Notez vos règles dès leur retour.');
  if(c.includes('allait'))T.push('<b>Allaitement</b> : l\'ovulation peut revenir avant les premières règles, et les cycles sont souvent irréguliers au début.');
  if(c.includes('fc'))T.push('<b>Fausses couches répétées</b> : un bilan est recommandé. Parlez-en à votre médecin, et prenez soin de vous : ce deuil est réel.');
  if(c.includes('clinique'))T.push('<b>Suivie en clinique</b> : suivez d\'abord le calendrier et les consignes de votre clinique. Notez vos traitements avec le bouton 💉 pour les voir dans le calendrier.');
  if(c.includes('partenaire'))T.push('<b>Partenaire</b> : un bilan des deux partenaires se fait en parallèle; parlez-en ensemble à votre médecin.');
  const m=+p.mois,lim=p.age==='40'?0:p.age==='35'?6:12;if(p.age==='40')T.push('<b>40 ans ou plus</b> : il est recommandé de consulter dès maintenant pour un bilan de fertilité.');else if(p.mois!=null&&p.mois!==''&&m>=lim)T.push('<b>Vous essayez depuis '+m+' mois</b> : c\'est le bon moment pour consulter'+(lim===6?' (recommandé après 6 mois à partir de 35 ans)':' (recommandé après 12 mois avant 35 ans)')+'.');
  return T}
function cartePourVous(){const T=pourVous();if(!T.length)return '<div class="card"><span class="eyebrow acc">Ma situation</span><p class="small muted" style="margin:4px 0 8px">SOPK, endométriose, contraception arrêtée, allaitement… Dites-le à l\'appli pour adapter vos repères et vos conseils.</p><button class="btn sm" data-fp-open="1">Compléter</button></div>';
  return '<div class="card ft-pv"><div class="row between"><span class="eyebrow acc">Pour vous</span><button class="btn sm ghost" data-fp-open="1">Modifier</button></div><ul class="clean dv-l">'+T.map(t=>'<li>'+t+'</li>').join('')+'</ul><p class="xs muted">Repères : <a href="https://www.asrm.org/practice-guidance/practice-committee-documents/" target="_blank" rel="noopener">ASRM (évaluation de la fertilité)</a> · <a href="https://www.monash.edu/medicine/mchri/pcos/guideline" target="_blank" rel="noopener">Ligne directrice internationale sur le SOPK</a>. Ils ne remplacent pas l\'avis de votre médecin.</p></div>'}
function compte(C){if(C.vide)return '';const n=Math.round((j0(C.prochain)-j0(Date.now()))/J);
  if(C.retard>=1)return '<div class="ft-cpt retard" data-dk="1" data-dt="1"><span>⏰</span><b>'+C.retard+' jour'+(C.retard>1?'s':'')+' de retard</b><small>Règles attendues le '+fd(C.prochain)+' · un test de grossesse est fiable</small></div>';
  if(n===0)return '<div class="ft-cpt"><span>🩸</span><b>Règles attendues aujourd\'hui</b><small>Selon vos cycles notés</small></div>';
  return '<div class="ft-cpt"><span>🩸</span><b>Règles dans '+n+' jour'+(n>1?'s':'')+'</b><small>Vers le '+fd(C.prochain,{weekday:'long',day:'numeric',month:'long'})+' · selon vos cycles notés</small></div>'}
function hero(C){if(C.vide)return '<div class="card ft-hero"><span class="eyebrow acc">Pour commencer</span><h2>Quand ont commencé vos dernières règles ?</h2><p class="small">Avec cette date, l\'appli calcule votre fenêtre fertile, votre ovulation et vos prochaines règles. Plus vous notez de cycles, plus c\'est précis.</p><button class="btn" data-ft-add="regles">'+icon('fa-droplet')+'Noter mes dernières règles</button></div>';
  const ch=chance(Date.now(),C),R=48,L=2*Math.PI*R,f=Math.min(1,C.jour/C.moy);
  return '<div class="card ft-hero"><div class="ft-anneau"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="'+R+'" fill="none" stroke="var(--soft2,#eee)" stroke-width="10"/><circle cx="60" cy="60" r="'+R+'" fill="none" stroke="'+ch[1]+'" stroke-width="10" stroke-linecap="round" stroke-dasharray="'+(L*f).toFixed(1)+' '+L.toFixed(1)+'" transform="rotate(-90 60 60)"/></svg><div><small>Jour</small><b>'+C.jour+'</b><small>du cycle</small></div></div>'+
    '<div class="ft-info"><span class="eyebrow acc">'+phase(C)+'</span><span class="pill" style="background:'+ch[1]+';color:#fff;align-self:flex-start">Chances aujourd\'hui : '+ch[0]+'</span>'+
    '<div class="small"><b>Ovulation</b> '+(j0(C.ov)<j0(Date.now())?'probable le ':'prévue le ')+fd(C.ov)+' <span class="muted">('+C.src+')</span></div>'+
    (irregulier()?'<div class="xs muted">Cycles irréguliers : dates approximatives, fiez-vous aux tests et à la glaire.</div>':'')+'<div class="small"><b>Fenêtre fertile</b> du '+fd(C.fen0)+' au '+fd(C.fen1)+'</div><div class="small"><b>Prochaines règles</b> vers le '+fd(C.prochain)+' · cycle moyen de '+C.moy+' jours</div></div>'+
    (C.retard>=1?'<div class="banner acc" style="grid-column:1/-1">'+icon('fa-baby')+'<div class="small">Vos règles ont '+C.retard+' jour'+(C.retard>1?'s':'')+' de retard : c\'est un bon moment pour faire un test de grossesse. <button class="btn sm" data-ft-add="testg">Noter un test</button></div></div>':'')+'</div>'}
function conseil(C){const i=((C&&C.jour)||new Date().getDate())%CONSEILS.length;return '<div class="card ft-conseil"><span class="eyebrow acc">Conseil du jour</span><p class="small" style="margin:4px 0 0">'+CONSEILS[i]+'</p></div>'}
/* message du jour, doux et encourageant, selon le moment du cycle */
function moment(C){if(C.vide)return null;const auj=j0(Date.now()),st=statut(auj,C),sg=suggestion(auj,C),dTest=j0(C.prochain);
  if(C.retard>=1||auj>=dTest)return {k:'test',ic:'🤰',t:'C\'est le temps de tester !',m:'Vos règles '+(C.retard>=1?'ont '+C.retard+' jour'+(C.retard>1?'s':'')+' de retard':'devraient arriver aujourd\'hui')+' : votre famille s\'agrandit peut-être… Faites un test avec la première urine du matin. On croise les doigts pour vous 💗',b:'testg',bt:'Noter mon test'};
  if(st==='ovul')return {k:'ovul',ic:'✨',t:'C\'est le grand jour !',m:'Votre ovulation est prévue aujourd\'hui : c\'est le moment le plus fertile de votre cycle. Profitez de ce moment à deux, tout en douceur 💕',b:'rapport',bt:'Noter un rapport'};
  if(st==='fertile')return {k:'fenetre',ic:'🌸',t:'Vous êtes dans votre fenêtre fertile',m:'Vos chances sont élevées ces jours-ci, jusqu\'au '+fd(C.ov)+'. Des rapports tous les 1 à 2 jours, sans pression : votre corps fait le reste 💗',b:'rapport',bt:'Noter un rapport'};
  if(sg==='lh')return {k:'lh',ic:'🧪',t:'C\'est le moment des tests d\'ovulation',m:'Votre fenêtre fertile approche (vers le '+fd(C.fen0)+'). Un test par jour, en après-midi, pour attraper votre pic 🌸',b:'ovul',bt:'Noter un test'};
  if(st==='regles')return {k:'regles',ic:'🌷',t:'Un nouveau cycle commence',m:'Nouveau départ, nouvelles chances. Prenez soin de vous : chaleur, repos et douceur ✨',b:'',bt:''};
  if(auj>j0(C.ov))return {k:'attente',ic:'🌙',t:'L\'attente…',m:'Les deux semaines d\'attente peuvent sembler longues. Faites-vous du bien. Un test sera fiable à partir du '+fd(C.prochain)+' 💫',b:'',bt:''};
  return {k:'avant',ic:'🌱',t:'Votre corps se prépare',m:'Votre fenêtre fertile commence vers le '+fd(C.fen0)+'. D\'ici là : acide folique, sommeil et petits plaisirs 🌼',b:'',bt:''}}
function carteMoment(C){const M=moment(C);if(!M)return '';return '<div class="card ft-mom ft-mom-'+M.k+'" data-dk="1" data-dt="1"><span class="ft-mom-ic">'+M.ic+'</span><div><b>'+M.t+'</b><p>'+M.m+'</p>'+(M.b?'<button class="btn sm" data-ft-add="'+M.b+'">'+M.bt+'</button>':'')+'</div></div>'}
/* à l'ouverture de l'appli : une petite fenêtre aux moments clés (début de la fenêtre fertile, jour du test), une fois par cycle */
function popMoment(){try{if(!modeConception()||document.getElementById('anniv')||document.getElementById('ftpop'))return;const l=document.getElementById('layer');if(l&&l.innerHTML)return;
  const C=cycle(),M=moment(C);if(!M||!['fenetre','ovul','test'].includes(M.k))return;const cle=(M.k==='ovul'?'fenetre':M.k)+'-'+C.deb,vus=S.parent.ftPop||[];if(vus.includes(cle))return;
  S.parent.ftPop=vus.concat([cle]).slice(-20);sauver();
  const o=document.createElement('div');o.id='ftpop';o.setAttribute('role','dialog');
  const conf=Array.from({length:14},(_,i)=>'<i style="left:'+(6+i*6.5)+'%;animation-delay:'+(i%5)*.3+'s">'+['🌸','💗','✨','🌷'][i%4]+'</i>').join('');
  o.innerHTML='<div class="an-fond"></div><div class="an-boite ftp">'+conf+'<div class="an-rond"><span>'+M.ic+'</span></div><h2>'+M.t+'</h2><p>'+M.m+'</p><button class="an-ok">OK</button></div>';
  document.body.appendChild(o);o.querySelector('.an-ok').onclick=()=>{o.classList.add('fin');setTimeout(()=>o.remove(),250)}}catch(e){}}
function accueilFT(){const C=cycle();setTimeout(popMoment,1200);let h=tete()+carteMoment(C)+hero(C)+compte(C);if(!C.vide)h+=semaine(C);
  /* l'accueil : des repères, puis on va au calendrier ou à la fertilité */
  let proch='';if(!C.vide){const a=avenirListe(C)[0];if(a)proch='<p class="small" style="margin:0 2px 12px">'+a[1]+' <b>'+a[2]+'</b> · '+fd(a[0],{weekday:'long',day:'numeric',month:'long'})+'</p>'}
  h+=proch+'<div class="ft-go"><button class="ft-g" data-act="tab" data-v="journal"><span>📅</span><b>Mon calendrier</b><small>Noter et voir mes jours, tests, rapports, traitements</small></button><button class="ft-g" data-act="tab" data-v="suivi"><span>🌱</span><b>Fertilité</b><small>Conseils, parcours, quand consulter</small></button></div>';
  return h}
function lig(l){return '<div class="li"><div class="ic">'+icon((LOGMETA[l.type]||['fa-circle'])[0])+'</div><div class="tx"><b>'+(LOGMETA[l.type]||['',''])[1]+' · '+fd(l.t,{day:'numeric',month:'short'})+' '+fmtT(l.t)+'</b><span>'+logText(l)+'</span></div>'+(l.img?'<img class="ft-mini" src="'+l.img+'" alt="Photo du test">':'')+'<button class="icon-btn" data-act="delLog" data-id="'+l.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></div>'}
const TRT={injection:'Injection',medicament:'Médicament',echo:'Échographie de suivi',sang:'Prise de sang',hcg:'Injection de déclenchement (hCG)',iiu:'Insémination (IIU)',ponction:'Ponction',transfert:'Transfert d\'embryon',beta:'Test de grossesse sanguin (bêta)',rdv:'Rendez-vous à la clinique',autre:'Autre'};
/* jours suggérés : tests d'ovulation (de 7 jours avant l'ovulation prévue jusqu'au jour prévu) et test de grossesse (jour des règles attendues), pour ce cycle et les 2 suivants */
function suggestion(d,C){const dd=j0(d);if(dd<j0(Date.now()))return '';const posCycle=(S.logs||[]).some(l=>l.type==='ovul'&&(l.res==='pos'||l.res==='pic')&&j0(l.t)>=C.deb);
  for(let k=0;k<3;k++){const p=j0(C.prochain+k*C.moy*J+J/2),o=k===0?j0(C.ov):j0(p-14*J+J/2);if(Math.round((p-dd)/J)===0)return 'tg';const e=Math.round((o-dd)/J),av=irregulier()?11:7,ap=irregulier()?-4:0;if(!(k===0&&posCycle)&&e>=ap&&e<=av)return 'lh'}return ''}
function fTraitement(){sheet('Traitement ou clinique','<p class="small muted">Pour un parcours de fertilité : injections, médicaments, échographies, prises de sang, insémination, transfert… Vous pouvez inscrire une date à venir.</p><label class="f">Quoi<select id="ft_tk">'+Object.entries(TRT).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><div class="grid2"><label class="f">Nom du médicament (si utile)<input id="ft_tn" placeholder="Ex. : FSH"></label><label class="f">Dose<input id="ft_td" placeholder="Ex. : 150 UI"></label></div>'+W()+'<label class="f">Répéter chaque jour pendant… (jours)<input type="number" id="ft_rep" inputmode="numeric" min="1" max="60" value="1"></label><label class="f">Note<input id="ft_tnote" placeholder="Ex. : à jeun, clinique de fertilité"></label><p class="xs muted">Suivez toujours le protocole de votre clinique : l\'appli sert d\'aide-mémoire.</p><button class="btn" data-ft-save="traitement">Enregistrer</button>')}
function avenir(C){const V=avenirListe(C);if(!V.length)return '';return '<div class="card ft-avenir"><span class="eyebrow acc">À venir</span><div class="list">'+V.map(x=>'<div class="li"><div class="ic">'+x[1]+'</div><div class="tx"><b>'+x[2]+'</b><span>'+fd(x[0],{weekday:'long',day:'numeric',month:'long'})+(x[3]?' · '+esc(x[3]):'')+'</span></div></div>').join('')+'</div></div>'}
function avenirListe(C){const auj=j0(Date.now()),A=[];
  if(!C.vide){for(let k=0;k<2;k++){const p=j0(C.prochain+k*C.moy*J+J/2),o=k===0?j0(C.ov):j0(p-14*J+J/2);if(o>=auj)A.push([Math.max(j0(o-7*J+J/2),auj),'🧪','Commencer les tests d\'ovulation','jusqu\'au '+fd(o)]);if(p>=auj)A.push([p,'🤰','Test de grossesse possible','si les règles n\'arrivent pas']);if(p>=auj)A.push([p,'🩸','Règles prévues','environ'])}}
  (S.logs||[]).filter(l=>l.type==='traitement'&&l.t>=auj).forEach(l=>A.push([l.t,'💉',TRT[l.k]||'Traitement',[l.nom,l.dose].filter(Boolean).join(' · ')+' · '+fmtT(l.t)]));
  A.sort((a,b)=>a[0]-b[0]);return A.slice(0,8)}
function calendrier(C){const base=new Date();base.setDate(1);base.setMonth(base.getMonth()+(S.ftMois||0));base.setHours(0,0,0,0);const m=base.getMonth(),y=base.getFullYear(),dec=(base.getDay()+6)%7,nb=new Date(y,m+1,0).getDate();
  let h='<div class="card"><p class="small muted" style="margin:0 0 8px;text-align:center">Touchez une date pour voir ou ajouter quelque chose 💗</p><div class="ft-cal-t"><button class="sb-fl" data-ft-mois="-1" aria-label="Mois précédent">'+icon('fa-chevron-left')+'</button><b>'+base.toLocaleDateString('fr-CA',{month:'long',year:'numeric'})+'</b><button class="sb-fl" data-ft-mois="1" aria-label="Mois suivant">'+icon('fa-chevron-right')+'</button></div><div class="ft-cal">'+['L','M','M','J','V','S','D'].map(x=>'<span class="ft-cal-h">'+x+'</span>').join('');
  for(let i=0;i<dec;i++)h+='<span></span>';
  for(let d=1;d<=nb;d++){const t=+new Date(y,m,d),s=C.vide?'':statut(t,C),L=(S.logs||[]).filter(l=>j0(l.t)===t),sel=S.ftJour===t;
    const sug=C.vide?'':suggestion(t,C),tr=L.some(l=>l.type==='traitement');
    const ic=[];if(L.some(l=>l.type==='rapport'&&!l.protege))ic.push('💗');else if(L.some(l=>l.type==='rapport'))ic.push('🤍');if(L.some(l=>l.type==='ovul'&&(l.res==='pos'||l.res==='pic')))ic.push('🌸');else if(L.some(l=>l.type==='ovul'))ic.push('🌱');if(L.some(l=>l.type==='temp'))ic.push('🌡️');if(L.some(l=>l.type==='testg'&&l.res==='pos'))ic.push('💖');const pts=ic.slice(0,2).join('');
    h+='<button class="ft-c '+s+(t===j0(Date.now())?' auj':'')+(sel?' sel':'')+'" data-ft-jour="'+t+'">'+(tr||sug?'<span class="ft-tag">'+(tr?'💉':'')+(sug==='lh'?'🧪':sug==='tg'?'🤰':'')+'</span>':'')+d+'<em>'+pts+'</em></button>'}
  h+='</div><div class="ft-leg"><span><i class="regles"></i>Règles</span><span><i class="prevu"></i>Règles prévues</span><span><i class="fertile"></i>Jours fertiles</span><span><i class="ovul"></i>Ovulation</span><span>💗 Rapport non protégé</span><span>🤍 Rapport protégé</span><span>🌸 Test d\'ovulation positif</span><span>🌱 Test d\'ovulation</span><span>🌡️ Température</span><span>🧪 Jour pour un test d\'ovulation</span><span>🤰 Jour pour un test de grossesse</span><span>💉 Traitement ou clinique</span></div>';
  if(false){const L=(S.logs||[]).filter(l=>j0(l.t)===S.ftJour&&LOGMETA[l.type]).sort((a,b)=>a.t-b.t),sg=C.vide?'':suggestion(S.ftJour,C);h+='<div class="sb-det"><div class="sb-det-t"><b>'+fd(S.ftJour,{weekday:'long',day:'numeric',month:'long'})+'</b><span>'+(C.vide?'':'Chances : '+chance(S.ftJour,C)[0])+(sg==='lh'?' · 🧪 bon jour pour un test d\'ovulation':sg==='tg'?' · 🤰 test de grossesse possible dès aujourd\'hui':'')+'</span></div>'+(L.length?'<div class="list">'+L.map(lig).join('')+'</div>':'<p class="small muted" style="margin:4px 0 0">Rien de noté ce jour-là.</p>')+'</div>'}
  return h+'</div>'}
function courbeT(C){if(C.vide)return '';const P=(C.bt&&C.bt.pts)||[];if(P.length<2)return '<div class="card"><span class="eyebrow acc">Température basale</span><p class="small muted">Notez votre température chaque matin : après quelques jours, la courbe apparaît ici et l\'appli repère la hausse qui suit l\'ovulation.</p></div>';
  const W=320,H=150,mn=Math.min(...P.map(p=>p.c),C.bt.cov||99)-.15,mx=Math.max(...P.map(p=>p.c))+.15,x=d=>14+((d-C.deb)/J)/(Math.max(C.moy,P.length+2)-1)*(W-28),y=c=>H-16-(c-mn)/(mx-mn)*(H-32);
  let s='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:auto" role="img" aria-label="Courbe de température basale">';
  if(C.bt.cov)s+='<line x1="10" x2="'+(W-10)+'" y1="'+y(C.bt.cov).toFixed(1)+'" y2="'+y(C.bt.cov).toFixed(1)+'" stroke="#9aa3ad" stroke-dasharray="4 4"/>';
  if(C.bt.ov)s+='<line x1="'+x(C.bt.ov).toFixed(1)+'" x2="'+x(C.bt.ov).toFixed(1)+'" y1="8" y2="'+(H-14)+'" stroke="#c2410c" stroke-dasharray="3 3"/>';
  s+='<polyline fill="none" stroke="var(--accent)" stroke-width="2.5" points="'+P.map(p=>x(p.d).toFixed(1)+','+y(p.c).toFixed(1)).join(' ')+'"/>'+P.map(p=>'<circle cx="'+x(p.d).toFixed(1)+'" cy="'+y(p.c).toFixed(1)+'" r="3.5" fill="var(--accent)"/>').join('')+'</svg>';
  return '<div class="card"><span class="eyebrow acc">Température basale · ce cycle</span>'+s+'<p class="xs muted">'+(C.bt.ov?'Hausse détectée : ovulation probablement le '+fd(C.bt.ov)+'. La température confirme l\'ovulation après coup.':'Ligne pointillée grise : la plus haute des 6 premières températures. Trois températures de suite au-dessus (la 3e d\'au moins 0,2 °C) confirment l\'ovulation.')+'</p></div>'}
function tests(){const L=LG('ovul').filter(l=>l.img).slice(-8).reverse();if(!L.length)return '';return '<div class="card"><span class="eyebrow acc">Mes tests d\'ovulation</span><div class="ft-tests">'+L.map(l=>'<figure><img src="'+l.img+'" alt="Test du '+fd(l.t)+'"><figcaption><span class="pill" style="background:'+(OV[l.res]||OV.neg)[1]+';color:#fff">'+(OV[l.res]||OV.neg)[0]+'</span>'+fd(l.t,{day:'numeric',month:'short'})+'</figcaption></figure>').join('')+'</div></div>'}
function historique(C){if(C.vide||!C.ecarts.length)return '';return '<div class="card"><span class="eyebrow acc">Mes cycles</span><div class="ft-hist">'+C.ecarts.slice(-8).map((e,i,a)=>'<div><b>'+e+'</b><span>jours</span></div>').join('')+'</div><p class="xs muted">Cycle moyen : '+C.moy+' jours. Un cycle entre 21 et 35 jours est considéré comme régulier.</p></div>'}
function reglages(){return '<div class="card"><span class="eyebrow acc">Mes repères</span><div class="grid2"><label class="f">Durée habituelle du cycle<input type="number" id="ft_cl" value="'+(+S.parent.cycleLen||28)+'" min="18" max="50"></label><label class="f">Durée des règles<input type="number" id="ft_rl" value="'+(+S.parent.reglesLen||5)+'" min="1" max="12"></label></div><button class="btn sm ghost" data-ft-reg="1">Enregistrer</button><p class="xs muted">Utilisé tant que vous n\'avez pas noté au moins 2 cycles.</p></div>'}
function bonneNouvelle(){let h='';
  h+='<div class="card tint"><span class="eyebrow acc">Bonne nouvelle ?</span><p class="small">Votre test de grossesse est positif ? Passez au suivi de grossesse : l\'appli calcule votre semaine à partir de vos dernières règles.</p><button class="btn ghost" data-ft-enceinte="1">'+icon('fa-person-pregnant')+'Je suis enceinte !</button></div>';
  return h}
function journalFT(){const C=cycle();return '<div class="sh"><span class="eyebrow acc">Essais bébé</span><h1>Mon cycle</h1></div>'+compte(C)+calendrier(C)+avenir(C)+courbeT(C)+tests()+historique(C)+cartePourVous()+reglages()+bonneNouvelle()}
const acc=(t,b)=>'<details class="acc"><summary>'+t+'<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body">'+b+'</div></details>';
const ul=a=>'<ul class="clean dv-l">'+a.map(x=>'<li>'+x+'</li>').join('')+'</ul>';
function guideFT(){return '<div class="sh"><span class="eyebrow acc">Essais bébé</span><h1>Fertilité et préconception</h1><p class="sub">Tout pour préparer une grossesse, comprendre votre cycle et vivre le parcours de fertilité</p></div>'+cartePourVous()+
 '<div class="card">'+acc('Préparer son corps avant la grossesse',ul(['<b>Acide folique</b> : une multivitamine avec 0,4 mg d\'acide folique chaque jour, au moins 3 mois avant la conception et pendant la grossesse (plus selon votre situation : demandez à votre médecin).','Un <b>rendez-vous préconception</b> : vaccins à jour (rubéole, varicelle), médicaments à revoir, maladies chroniques bien contrôlées, examen de dépistage.','Arrêter le tabac, l\'alcool et le cannabis; caféine limitée à environ 300 mg par jour.','Un poids santé, de l\'activité physique régulière et un bon sommeil aident l\'ovulation.','Le partenaire aussi : la fabrication des spermatozoïdes prend environ 3 mois. Tabac, alcool, chaleur et certains médicaments les affectent.']))+
 acc('Comprendre son cycle',ul(['Le cycle commence le <b>1er jour des règles</b>. Il dure en moyenne 28 jours, mais de 21 à 35 jours est normal.','L\'<b>ovulation</b> a lieu environ 14 jours avant les règles suivantes, pas forcément au jour 14.','La <b>fenêtre fertile</b> : les 5 jours avant l\'ovulation et le jour même. Les spermatozoïdes vivent jusqu\'à 5 jours, l\'ovule 12 à 24 heures.','Signes de l\'ovulation : glaire claire et filante, test d\'ovulation positif, légère douleur d\'un côté du ventre, hausse de la température après.']))+
 acc('Les meilleurs moments',ul(['Des rapports <b>tous les 1 à 2 jours pendant la fenêtre fertile</b>, ou 2 à 3 fois par semaine tout au long du cycle.','Pas besoin de position particulière ni de rester allongée longtemps après.','Évitez de transformer les rapports en « devoirs » : l\'intimité compte aussi pour le couple.']))+
 acc('Tests d\'ovulation (LH)',ul(['Commencez quelques jours avant l\'ovulation prévue (l\'appli vous l\'indique).','En après-midi, à la même heure, en buvant moins dans les 2 heures avant.','<b>Positif</b> quand la ligne de test est aussi foncée ou plus foncée que la ligne de contrôle : l\'ovulation suit souvent dans les 24 à 36 heures.','Prenez une photo à chaque test dans l\'appli : vous verrez la ligne foncer jour après jour.','SOPK ou cycles irréguliers : les tests peuvent être trompeurs, parlez-en à votre médecin.']))+
 acc('Température basale',ul(['Au réveil, avant de vous lever, à la même heure, après au moins 3 heures de sommeil.','Après l\'ovulation, la température monte de 0,2 à 0,5 °C et reste haute jusqu\'aux règles.','Elle confirme l\'ovulation après coup : utile pour connaître votre rythme d\'un cycle à l\'autre.','Si elle reste haute plus de 18 jours après l\'ovulation, faites un test de grossesse.']))+
 acc('Quand consulter',ul(['Après <b>12 mois</b> d\'essais si vous avez moins de 35 ans.','Après <b>6 mois</b> si vous avez 35 ans ou plus, et <b>tout de suite</b> à 40 ans et plus.','Sans attendre si : cycles très irréguliers ou absents, règles très douloureuses (endométriose), SOPK, infection ou chirurgie pelvienne passée, 2 fausses couches ou plus, cancer traité, ou problème connu chez le partenaire.']))+
 acc('Le parcours de fertilité',ul(['<b>Le bilan</b> : prises de sang (hormones, réserve ovarienne AMH), échographie, examen des trompes, spermogramme pour le partenaire.','<b>Les traitements</b> : médicaments pour stimuler l\'ovulation (létrozole, clomifène), insémination intra-utérine (IIU), fécondation in vitro (FIV), selon la cause.','<b>Au Québec</b> : le Programme de procréation médicalement assistée couvre un cycle de FIV à vie (jusqu\'à 2 stimulations) et jusqu\'à 6 inséminations par naissance vivante, et un crédit d\'impôt existe pour les frais non couverts.','<b>Au Nouveau-Brunswick</b> : un programme provincial rembourse un cycle de FIV ou d\'insémination par ménage (voir la page du gouvernement pour les conditions).','<b>Partout au Canada</b> : plusieurs frais de fertilité sont admissibles au crédit d\'impôt fédéral pour frais médicaux.','<b>En France</b> : l\'Assurance maladie prend en charge l\'aide médicale à la procréation sous conditions d\'âge.']))+
 acc('Prendre soin de vous',ul(['Les mois d\'attente peuvent être lourds : déceptions, comparaisons, annonces des autres. Vos émotions sont légitimes.','Parlez-en à votre partenaire, à votre doula, à une personne de confiance ou à un professionnel en santé mentale spécialisé en fertilité.','Une fausse couche est fréquente (environ 15 à 20 % des grossesses connues) et n\'est presque jamais causée par ce que vous avez fait. Vous pouvez demander du soutien pour ce deuil.','Prenez des pauses du suivi si vous en avez besoin : votre bien-être passe avant les graphiques.']))+
 acc('Test de grossesse',ul(['Le plus fiable : à partir du jour des règles attendues, avec la première urine du matin.','Un test négatif trop tôt peut devenir positif quelques jours plus tard : refaites-le si les règles n\'arrivent pas.','Positif ? Touchez « Je suis enceinte ! » sur l\'accueil : l\'appli passe au suivi de grossesse et calcule votre semaine.']))+
 '<p class="xs muted" style="margin-top:8px">Sources : <a href="https://www.pregnancyinfo.ca/fr/" target="_blank" rel="noopener">SOGC (grossesse-info)</a> · <a href="https://www.canada.ca/fr/sante-canada/services/aliments-nutrition/saine-alimentation/vitamines-mineraux/acide-folique.html" target="_blank" rel="noopener">Santé Canada, acide folique</a> · <a href="https://www.quebec.ca/famille-et-soutien-aux-personnes/grossesse-parentalite/procreation-assistee/programme-procreation-medicalement-assistee" target="_blank" rel="noopener">Québec, procréation médicalement assistée</a> · <a href="https://www.gnb.ca/fr/nouvelles/n-b.2025.04.financement-pour-appuyer-lacces-aux-traitements-de-fertilite.html" target="_blank" rel="noopener">Nouveau-Brunswick, traitements de fertilité</a></p></div>'}
