function menuJour(t){const C=cycle(),auj=j0(Date.now()),futur=t>auj,L=(S.logs||[]).filter(l=>j0(l.t)===t&&LOGMETA[l.type]).sort((a,b)=>a.t-b.t),sg=C.vide?'':suggestion(t,C),st=C.vide?'':statut(t,C);
  const etat={regles:'🩸 Jour de règles',prevu:'🩸 Règles prévues',fertile:'🌼 Jour fertile',ovul:'🌸 Ovulation probable'}[String(st).split(' ')[0]]||'';
  const B=futur?[['traitement','💉','Traitement ou rendez-vous'],['rapport','❤️','Rapport']]:[['regles','🩸','Règles'],['rapport','❤️','Rapport'],['ovul','🧪','Test ovulation'],['temp','🌡️','Température'],['glaire','💧','Glaire'],['testg','🤰','Test grossesse'],['traitement','💉','Traitement']];
  sheet(fd(t,{weekday:'long',day:'numeric',month:'long'}),
    (etat||!C.vide?'<p class="small" style="margin:0 0 6px">'+[etat,C.vide?'':'Chances : '+chance(t,C)[0]].filter(Boolean).join(' · ')+'</p>':'')+
    (sg==='lh'?'<p class="small">🧪 Bon jour pour un test d\'ovulation.</p>':sg==='tg'?'<p class="small">🤰 Un test de grossesse est possible dès ce jour.</p>':'')+
    (L.length?'<span class="eyebrow acc">Déjà noté</span><div class="list" style="margin-bottom:10px">'+L.map(lig).join('')+'</div>':'')+
    '<span class="eyebrow acc">'+(futur?'Planifier pour ce jour':'Ajouter pour ce jour')+'</span><div class="ft-btns" style="margin-top:6px">'+B.map(b=>'<button class="ft-b" data-ft-jadd="'+b[0]+'" data-t="'+t+'"><span>'+b[1]+'</span><b>'+b[2]+'</b></button>').join('')+'</div>')}
function dateCible(t){const d=new Date(t),n=new Date();d.setHours(n.getHours(),n.getMinutes(),0,0);if(d>n&&j0(t)<=j0(Date.now()))d.setTime(n.getTime());
  const pad=x=>String(x).padStart(2,'0'),ds=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
  const a=document.getElementById('m_t');if(a){if(a.max&&ds+'T'>a.max)a.removeAttribute('max');a.value=ds+'T'+pad(d.getHours())+':'+pad(d.getMinutes())}
  const b=document.getElementById('ft_d');if(b)b.value=ds;const c=document.querySelector('#layer input[type=date]:not(#ft_d)');if(c&&!c.value)c.value=ds}
